package com.hms.queue;
import com.hms.appointments.*; import com.hms.tenancy.*; import jakarta.validation.Valid; import java.time.LocalDate; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/public/hospitals/{tenantSlug}/check-in") public class PublicCheckInController {private final TenantRepository tenants;private final AppointmentRepository appointments;private final PatientRepository patients;private final QueueTokenRepository tokens;public PublicCheckInController(TenantRepository t,AppointmentRepository a,PatientRepository p,QueueTokenRepository q){tenants=t;appointments=a;patients=p;tokens=q;} @PostMapping @ResponseStatus(HttpStatus.CREATED) public PublicCheckInDto checkIn(@PathVariable String tenantSlug,@Valid @RequestBody PublicCheckInRequest request){UUID tenant=tenants.findBySlug(tenantSlug).filter(t->t.getStatus()!=TenantStatus.SUSPENDED&&t.getStatus()!=TenantStatus.CANCELLED&&t.getStatus()!=TenantStatus.EXPIRED).map(Tenant::getId).orElseThrow(()->new IllegalArgumentException("Hospital is not accepting check-in"));Appointment appointment=appointments.findById(request.appointmentId()).filter(a->a.getTenantId().equals(tenant)).orElseThrow(()->new IllegalArgumentException("Appointment not found"));patients.findById(appointment.getPatientId()).filter(p->p.getTenantId().equals(tenant)&&p.getPhone().equals(request.phone().trim())).orElseThrow(()->new IllegalArgumentException("Appointment not found"));QueueToken existing=tokens.findByAppointmentId(appointment.getId()).orElse(null);if(existing!=null)return new PublicCheckInDto(appointment.getId(),existing.getId(),existing.getTokenNumber(),existing.getTokenDate(),existing.getStatus());if(appointment.getStatus()!=AppointmentStatus.CONFIRMED)throw new IllegalArgumentException("Only confirmed appointments can be checked in");appointment.updateStatus(AppointmentStatus.CHECKED_IN);appointments.save(appointment);LocalDate date=appointment.getStartsAt().toLocalDate();int number=tokens.findFirstByTenantIdAndDoctorIdAndTokenDateOrderByTokenNumberDesc(tenant,appointment.getDoctorId(),date).map(x->x.getTokenNumber()+1).orElse(1);QueueToken token=tokens.save(new QueueToken(tenant,appointment.getId(),appointment.getDoctorId(),date,number));return new PublicCheckInDto(appointment.getId(),token.getId(),token.getTokenNumber(),token.getTokenDate(),token.getStatus());}}
